def solution(input_str):
    import sys
    from collections import deque

    lines = input_str.strip().split('\n')
    if not lines:
        return '-1'

    n, m = map(int, lines[0].split())

    if n == 0:
        return '-1'

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components using BFS
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            count = 0
            queue = deque([i])
            visited[i] = True

            while queue:
                node = queue.popleft()
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            components.append(count)

    if not components:
        return '-1'

    # Generate lucky numbers up to n
    lucky_numbers = []

    def generate_lucky(current_num, length):
        if current_num > n:
            return
        if length == 0:
            lucky_numbers.append(current_num)
            return
        generate_lucky(current_num * 10 + 4, length - 1)
        generate_lucky(current_num * 10 + 7, length - 1)

    for length in range(1, 7):
        generate_lucky(0, length)
    lucky_numbers.sort()

    # Use DP with memoization to find minimum components for each lucky number
    # dp[s] = minimum number of components needed to achieve sum s
    MAX_LUCKY = lucky_numbers[0] if lucky_numbers else 0 + 77

    if not lucky_numbers:
        return '-1'

    max_lucky_to_check = MAX_LUCKY

    # Sort components in descending order for better pruning
    components.sort(reverse=True)

    # DP approach: for each lucky number, find min components needed
    from functools import lru_cache

    min_components_for_target = {}

    def find_min_components(target, sorted_components, idx, current_sum, count):
        if current_sum == target:
            return count
        if current_sum > target:
            return float('inf')
        if idx == len(sorted_components):
            return float('inf')

        # Pruning: if we can't possibly reach target
        if current_sum + sum(sorted_components[idx:]) < target:
            return float('inf')

        # Option 1: Skip current component
        res1 = find_min_components(target, sorted_components, idx + 1, current_sum, count)

        # Option 2: Use current component if not already at target
        if res1 == float('inf') and current_sum + sorted_components[idx] <= target:
            res2 = find_min_components(target, sorted_components, idx + 1, 
                                      current_sum + sorted_components[idx], count + 1)
            return min(res1, res2)

        return res1

    # For each lucky number, find if achievable and minimum components
    min_roads = float('inf')

    for target in lucky_numbers:
        if target <= n:
            # Check if target can be formed
            result = find_min_components(target, components, 0, 0, 0)
            if result < float('inf'):
                roads_needed = result - 1
                min_roads = min(min_roads, roads_needed)

    if min_roads == float('inf'):
        return '-1'

    return str(min_roads)

