def solution(input_str):
    lines = input_str.strip().split('\n')

    # Parse into a list of strings without spaces
    grid = [line.replace(' ', '') for line in lines if line.strip()]

    # Pad shorter rows to make it easier to process
    grid = [[c for c in row] for row in grid]
    max_len = max(len(row) for row in grid)
    for i in range(len(grid)):
        while len(grid[i]) < max_len:
            grid[i].append('.')

    memo = {}

    def get_key(board):
        return tuple(tuple(row) for row in board)

    def get_moves(board):
        bd = [list(row) for row in board]
        moves = []

        # Direction 1: horizontal lines (same row)
        for r in range(len(bd)):
            for start in range(len(bd[r])):
                for end in range(start, len(bd[r])):
                    if all(bd[r][c] == 'O' for c in range(start, end + 1)):
                        new_bd = [row[:] for row in bd]
                        new_bd[r][start:end+1] = ['.'] * (end - start + 1)
                        moves.append(get_key(new_bd))

        # Direction 2: diagonal 1 (down-right, going from left to right in columns)
        for c in range(max_len):
            for start_r in range(len(bd)):
                for end_r in range(start_r, len(bd)):
