            if node == end:
                return True
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    min_budget = float('inf')
    best_roads = []

    # Check with 0 roads closed
    if not can_reach(s, t, set()):
        return "0\n0\n"

    # Try each road individually
    for u, v, w, idx in roads:
        if not can_reach(s, t, {idx}):
            if w < min_budget:
