        line = input_lines[i].strip()
        if line:
            u, v = map(int, line.split())
            adj[u].append(v)

    # Compute all-pairs shortest paths using BFS from each node
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        dist[start][start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[start][v] == float('inf'):
                    dist[start][v] = dist[start][u] + 1
                    q.append(v)

    # Precompute for each node: sorted list of (distance, node) for all other nodes
    # This helps in efficiently finding the max distance to any unvisited node
    node_dists = []
    for start in range(1, n + 1):
        dlist = []
        for j in range(1, n + 1):
            if dist[start][j] != float('inf'):
                dlist.append((dist[start][j], j))
        dlist.sort()
        node_dists.append(dlist)

    max_total = -1
    best = None

    # Iterate through all possible triples (a, b, c) and find best d
    # Using node_dists precomputed data for efficiency
    for a in range(1, n + 1):
        for b in range(1, n + 1):
            if a == b:
                continue
            if dist[a][b] == float('inf'):
                continue
            for c in range(1, n + 1):
                if c == a or c == b:
                    continue
                if dist[b][c] == float('inf'):
                    continue

                # Find best d (d != a, b, c) maximizing dist[c][d]
                forb = {a, b, c}
                tdlist = node_dists[c - 1]  # c is 1-indexed
                best_d = -1
                best_dist = -1

                for d_val, d_node in tdlist:
                    if d_node in forb:
                        continue
                    if d_dist > best_dist:
                        best_dist = d_dist
                        best_d = d_node

                if best_d != -1 and dist[c][best_d] != float('inf'):
                    total = dist[a][b] + dist[b][c] + dist[c][best_d]
                    if total > max_total:
                        max_total = total
                        best = (a, b, c, best_d)

    if best:
        return " ".join(map(str, best))
    return ""
