Looking at this problem, I need to solve a graph coloring problem where:
- Each vertex in tree T has a set of ice cream types
- Two ice cream types are adjacent in graph G if they appear together at any vertex
- Need to find the minimum colors (chromatic number) and a valid coloring

**Key Insight**: The minimum number of colors equals the maximum number of ice cream types that appear together at any single vertex. This is because those types form a clique in G, and we can achieve this bound with greedy coloring.

```python
# Your solution code here
import sys
from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "1\n1 "

    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])

    # Parse vertex ice cream data
    # vertex_to_ices[i] = list of ice creams at vertex i
    vertex_to_ices = {}
    for i in range(1, n + 1):
        parts = lines[i].split()
        si = int(parts[0])
        if si > 0:
            vertex_to_ices[i] = [int(x) for x in parts[1:]]

    # Find chromatic number = max clique size = max ice creams at any vertex
    chromatic = max((len(ices) for ices in vertex_to_ices.values()), default=1)
    chromatic = max(1, chromatic)

    # Build adjacency: two ice creams are adjacent if they appear together
    # adj[ice_cream] = set of adjacent ice creams
    adj = {}
    for vertex, ices in vertex_to_ices.items():
        if len(ices) > 1:
            for i in range(len(ices)):
                if ices[i] not in adj:
                    adj[ices[i]] = set()
                for j in range(i + 1, len(ices)):
                    adj[ices[i]].add(ices[j])
                    adj[ices[j]].add(ices[i])

    # Greedy coloring: for each ice cream, assign smallest available color
    colors = {}
    for ice_cream in range(1, m + 1):
        used = set()
        for neighbor in adj.get(ice_cream, []):
            used.add(colors[neighbor])
        color = 1
        while color in used:
            color += 1
        colors[ice_cream] = color

    # Format output
    result = str(chromatic) + '\n' + ' '.join(str(colors[i]) for i in range(1, m + 1))
    return result
