Looking at this problem, I need to find when the last "hole" (closed white region) disappears as circles grow. The key insight is that holes disappear when the three circles forming them meet at their circumcenter. The answer is the maximum circumradius among all valid triangles where the circumcenter lies strictly inside the triangle.

```python
import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    circles = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        circles.append((x, y))

    if n < 3:
        return '-1'

    def dist(p1, p2):
        return math.sqrt((p1[0] - p2[0])**2 + **(p1[1] - p2[1])2)

    def circumradius(a, b, c):
        s = (a + b + c) / 2
        area_sq = s * (s - a) * (s - b) * (s - c)
        area = math.sqrt(max(0, area_sq))
        if area < 1e-9:
            return float('inf')
        return (a * b * c) / (4 * area)

    def circumcenter(p1, p2, p3):
        dx1 = p2[0] - p1[0]
        dy1 = p2[1] - p1[1]
        dx2 = p3[0] - p2[0]
        dy2 = p3[1] - p2[1]

        det = dx1 * dy2 - dy1 * dx2
        if abs(det) < 1e-9:
            None, None

        rhs1 = 0.5 * (p2[0]**2 + p2[1]**2 - p1[0]**2 - p1[1]**2)
        rhs2 = 0.5 * (p3[0]**2 + p3[1]**2 - p2[0]**2 - p2[1]**2)

        cx = (rhs1 * dy2 - rhs2 * dy1) / det
        cy = (rhs2 * dx1 - rhs1 * dx2) / det
        return cx, cy

    def is_strictly_inside(px, py, p1, p2, p3):
        def cross_product(ax, ay, bx, by):
            return ax * by - ay * bx

        cp1 = cross_product(p1[0]-p2[0], p1[1]-p2[1], px-p2[0], py-p2[1])
        cp2 = cross_product(p2[0]-p3[0], p2[1]-p3[1], px-p3[0], py-p3[1])
        cp3 = cross_product(p3[0]-p1[0], p3[1]-p1[1], px-p1[0], py-p1[1])

        return (cp1 > 0 and cp2 > 0 and cp3 > 0) or (cp1 < 0 and cp2 < 0 and cp3 < 0)

    max_ans = float('-inf')
    has_hole = False

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                p1, p2, p3 = circles[i], circles[j], circles[k]

                cx, cy = circumcenter(p1, p2, p3)

                if cx is not None and cy is not None:
                    if is_strictly_inside(cx, cy, p1, p2, p3):
                        r = circumradius(dist(p1, p2), dist(p2, p3), dist(p3, p1))
                        if r < float('inf'):
                            max_ans = max(max_ans, r)
                            has_hole = True

    if not has_hole:
        return '-1'

    return '{:.6f}'.format(max_ans)
```

This solution finds the maximum circumradius among all triangles formed by circle centers where the circumcenter lies strictly inside the triangle. Each such configuration represents a potential hole that disappears at its circumradius. If no valid triangles exist, returns -1.

