Looking at this problem, I need to implement a solution that processes matrix operations including cyclic shifts and inverse permutations. Let me trace through the logic:

1. **R/L/D/U**: These are cyclic shifts of the matrix (columns left/right, rows up/down)
2. **I**: Invert each row permutation (if row[i] = j, then new_row[j] = i+1)
3. **C**: Invert each column permutation

I'll use a matrix representation and handle each operation directly. For large inputs, using Python's `deque.rotate()` makes column shifts efficient.

```python
def solution(input_data):
    from collections import deque

    lines = input_data.strip().split('\n')
    idx = 0

    def solve():
        t = int(lines[idx])
        idx += 1

        results = []

        for _ in range(t):
            n, m = int(lines[idx]), int(lines[idx+1])
            idx += 2

            # Initialize matrix with deque for each row
            matrix = [deque(map(int, lines[idx].split())) for _ in range(n)]
            idx += 1

            ops = lines[idx]
            idx += 1

            for op in ops:
                if op == 'R':
                    # Left cyclic shift (L): rotate by +1
                    for row in matrix:
                        row.rotate(1)
                elif op == 'L':
                    # Right cyclic shift (R): rotate by -1
                    for row in matrix:
                        row.rotate(-1)
                elif op == 'D':
                    # Down shift: last row becomes first
                    if n > 0:
                        bottom = matrix.pop()
                        matrix.insert(0, bottom)
                elif op == 'U':
                    # Up shift: first row becomes last
                    if n > 0:
                        top = matrix.popleft()
                        matrix.append(top)
                elif op == 'I':
                    # Invert each row
                    new_matrix = []
                    for row in matrix:
                        inv = [0] * (n + 1)
                        for j, val in enumerate(row):
                            inv[val] = j + 1
                        new_matrix.append(inv[1:])
                    matrix = new_matrix
                elif op == 'C':
                    # Invert each column
                    new_matrix = [[0] * n for _ in range(n)]
                    for r in range(n):
                        for c in range(n):
                            new_matrix[c][r] = matrix[r][c]
                    matrix = new_matrix

            # Format output
            formatted = []
            for row in matrix:
                formatted.append(' '.join(map(str, row)))
            results.append('\n'.join(formatted))

        return '\n\n'.join(results)

    return solve()
