import math
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    adj = [[] for _ in range(n + 1)]
    for i in range(2, len(lines)):
        line = lines[i].strip()
        if line:
            parts = line.split()
            if len(parts) >= 2:
                u, v = int(parts[0]), int(parts[1])
                adj[u].append(v)
                adj[v].append(u)

    # Part 1: sum of deg[u] * a[u] for all nodes
    deg = [0] * (n + 1)
    for u in range(1, n + 1):
        deg[u] = len(adj[u])

    part1 = sum(deg[u] * a[u - 1] for u in range(1, n + 1))

    # Part 2: contribution from all node pairs with distance >= 2
    part2 = 0
    for start in range(1, n + 1):
        dist = {start: 0}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    queue.append(v)

        for v in range(1, n + 1):
            if v != start and v in dist:
                d = dist[v]
                if d >= 2:
                    part2 += math.ceil(math.log2(d)) * min(a[start - 1], a[v - 1])

    return str(part1 + part2)
```

This solution parses the input tree, computes the degree-weight sum for part 1, and calculates pair-distance contributions for part 2 where the distance between nodes is 2 or greater.

