            # Check clockwise direction (from i to j)
            can_see_cw = True
            for k in range(i + 1, j):
                if heights[k] > max(heights[i], heights[j]):
                    can_see_cw = False
                    break

            if can_see_cw:
                count += 1
                continue

            # Check counter-clockwise direction
            can_see_ccw = True

            if i < j:
                # Go backwards from j to i
                for k in range(j - 1, i - 1, -1):
                    if heights[k] > max(heights[i], heights[j]):
                        can_see_ccw = False
                        break
            else:
                # Wrap around counter-clockwise
                # First segment: from j-1 down to 0
                for k in range(j - 1, -1, -1):
                    if heights[k] > max(heights[i], heights[j]):
                        can_see_ccw = False
                        break

                # Second segment: from n+i-1 down to i (circular)
                if can_see_ccw:
                    for k in range(n + i - 1, i - 1, -1):
                        if heights[k % n] > max(heights[i], heights[j]):
                            can_see_ccw = False
                            break

            if can_see_ccw:
                count += 1

    return str(count + '\n')
