from collections import defaultdict, deque
import sys

class Solution:
    def __init__(self, n, k, edges):
        self.n = n
        self.k = k  
        self.adj = defaultdict(list)
        self.parent = [0] * (n + 1)

        for u, v in edges:
            self.adj[u].append(v)
            self.adj[v].append(u)

    def bfs(self):
        self.depth = [0] * (self.n + 1)
        self.visited = [False] * (self.n + 1)
        self.visited[1] = True
        order = [1]
        d = 0

        for u in order:
            for v in self.adj[u]:
                if not self.visited[v]:
                    self.visited[v] = True
                    self.parent[v] = u
                    self.depth[v] = self.depth[u] + 1
                    order.append(v)
                    d += 1
        return order

    def lca(self, u, v):
        while self.depth[u] > self.depth[v]:
            u = self.parent[u]
        while self.depth[v] > self.depth[u]:
            v = self.parent[v]
        while u != v:
            u = self.parent[u]
            v = self.parent[v]
        return u

    def distance(self, u, v):
        root = self.lca(u, v)
        return self.depth[u] + self.depth[v] - 2 * self.depth[root]

    def solve(self):
        h_coords = [node for i, node in enumerate(self.parent[1:self.n]) if i % 2 == 0]
        return h_coords

