from collections import defaultdict, deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())

    if n <= 1:
        return "0\n"

    adj = defaultdict(list)
    for line in lines[1:]:
        if line.strip():
            u, v = map(int, line.split())
            adj[u].append(v)
            adj[v].append(u)

    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    q = [1]
    visited = {1}

    idx = 0
    while idx < len(q):
        u = q[idx]
        idx += 1
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                parent[v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    def tree_dist(u, v):
        a, b = u, v
        while a != b:
            if depth[a] > depth[b]:
                a = parent[a]
            elif depth[b] > depth[a]:
                b = parent[b]
            else:
                a = parent[a]
                b = parent[b]
        return depth[u] + depth[v] - 2 * depth[a]

    centroid = 1
    min_max = float('inf')
    for node in range(1, n + 1):
        mx = max(tree_dist(node, other) for other in range(1, n + 1))
        if mx < min_max:
            min_max = mx
            centroid = node

    shortcuts = []
    for node in range(1, n + 1):
        if node != centroid:
            shortcuts.append((node, centroid))

    shortcuts = sorted(set(shortcuts))
    shortcuts = shortcuts[:10 * n]

    return str(len(shortcuts)) + '\n' + '\n'.join(f"{u} {v}" for u, v in shortcuts) + '\n'
